// Some portions generated by Codex
package org.eclipse.rdf4j.benchmark;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class DockerBenchmarkWrapperTest {

	private static final String BENCHMARK_CLASS = "org.example.QueryBenchmark";

	@TempDir
	Path project;

	@BeforeEach
	void copyWrapper() throws IOException {
		Path repository = Path.of("").toAbsolutePath();
		while (repository != null
				&& !Files.isRegularFile(repository.resolve("scripts/run-single-benchmark-docker.sh"))) {
			repository = repository.getParent();
		}
		if (repository == null) {
			throw new IOException("Cannot locate the repository benchmark wrapper");
		}
		Files.createDirectories(project.resolve("scripts"));
		Files.copy(repository.resolve("scripts/run-single-benchmark-docker.sh"),
				project.resolve("scripts/run-single-benchmark-docker.sh"));
	}

	@Test
	void explicitModuleIgnoresArchivedSourceCopies() throws Exception {
		pom("", "<modules><module>core/benchmark</module></modules>");
		benchmark("core/benchmark", "themeName");
		benchmark("work/saved/core/benchmark", "archivedTheme");

		Result result = run("--module", "core/benchmark", "--class", BENCHMARK_CLASS, "--method", "executeQuery",
				"--param", "themeName=VALUE");

		assertEquals(0, result.status, result.output);
		assertTrue(result.output.contains("--module core/benchmark"), result.output);
		assertTrue(result.output.contains("--param themeName=VALUE"), result.output);
	}

	@Test
	void explicitModuleSelectsItsOwnFlexibleParameters() throws Exception {
		pom("", "<modules><module>first</module><module>second</module></modules>");
		benchmark("first", "firstTheme");
		benchmark("second", "secondTheme");

		Result result = run("--module", "second", "--class", BENCHMARK_CLASS, "--method", "executeQuery", "VALUE");

		assertEquals(0, result.status, result.output);
		assertTrue(result.output.contains("--param secondTheme=VALUE"), result.output);
	}

	@Test
	void shorthandSearchesNestedReactorModulesOnly() throws Exception {
		pom("", "<modules><module>core</module></modules>");
		pom("core", "<modules><module>nested/benchmark</module></modules>");
		benchmark("core/nested/benchmark", "themeName");
		benchmark("work/saved/core/nested/benchmark", "archivedTheme");

		Result result = run(BENCHMARK_CLASS + ".executeQuery", "VALUE");

		assertEquals(0, result.status, result.output);
		assertTrue(result.output.contains("--module core/nested/benchmark"), result.output);
		assertTrue(result.output.contains("--param themeName=VALUE"), result.output);
	}

	@Test
	void shorthandIncludesProfileModulesAndPathsWithSpaces() throws Exception {
		pom("", "<profiles><profile><id>benchmarks</id><modules><module>benchmark module</module></modules>"
				+ "</profile></profiles>");
		benchmark("benchmark module", "themeName");

		Result result = run(BENCHMARK_CLASS + ".executeQuery");

		assertEquals(0, result.status, result.output);
		assertTrue(result.output.contains("--module benchmark\\ module"), result.output);
	}

	@Test
	void shorthandReportsAmbiguityBetweenRealModules() throws Exception {
		pom("", "<modules><module>first</module><module>second</module></modules>");
		benchmark("first", "themeName");
		benchmark("second", "themeName");

		Result result = run(BENCHMARK_CLASS + ".executeQuery");

		assertNotEquals(0, result.status, result.output);
		assertTrue(result.output.contains("resolves to multiple modules"), result.output);
		assertTrue(result.output.contains("first/src/test/java/"), result.output);
		assertTrue(result.output.contains("second/src/test/java/"), result.output);
	}

	@Test
	void explicitModuleDoesNotFallBackToAnotherModule() throws Exception {
		pom("", "<modules><module>first</module><module>second</module></modules>");
		benchmark("first", "themeName");
		pom("second", "");

		Result result = run("--module", "second", "--class", BENCHMARK_CLASS, "--method", "executeQuery");

		assertNotEquals(0, result.status, result.output);
		assertTrue(result.output.contains("Could not resolve benchmark class"), result.output);
	}

	@Test
	void repeatedModuleDeclarationsDoNotCreateAmbiguity() throws Exception {
		pom("", "<modules><module>benchmark</module></modules>"
				+ "<profiles><profile><id>again</id><modules><module>benchmark</module></modules></profile></profiles>");
		benchmark("benchmark", "themeName");

		Result result = run(BENCHMARK_CLASS + ".executeQuery");

		assertEquals(0, result.status, result.output);
	}

	private void benchmark(String module, String parameter) throws IOException {
		pom(module, "");
		Path source = project.resolve(module).resolve("src/test/java/org/example/QueryBenchmark.java");
		Files.createDirectories(source.getParent());
		Files.writeString(source, "package org.example;\npublic class QueryBenchmark {\n"
				+ "  @Param({\"VALUE\"})\n  public String " + parameter + ";\n}\n");
	}

	private void pom(String module, String contents) throws IOException {
		Path directory = project.resolve(module);
		Files.createDirectories(directory);
		Files.writeString(directory.resolve("pom.xml"),
				"<project xmlns=\"http://maven.apache.org/POM/4.0.0\">" + contents + "</project>\n");
	}

	private Result run(String... arguments) throws IOException, InterruptedException {
		List<String> command = new ArrayList<>(List.of("bash", "scripts/run-single-benchmark-docker.sh"));
		command.addAll(List.of(arguments));
		command.add("--dry-run");
		Process process = new ProcessBuilder(command).directory(project.toFile()).redirectErrorStream(true).start();
		String output = new String(process.getInputStream().readAllBytes(), StandardCharsets.UTF_8);
		return new Result(process.waitFor(), output);
	}

	private record Result(int status, String output) {
	}
}
